import { MOVIE_PLAYER_ID } from '@content/scripts/media/shared/constants';
import {
  MID_MEDIA_IFRAME_ID,
  MID_MEDIA_OVERLAY_ID,
} from '@content/scripts/media/midMedia/constants';
import { getLocalStorageData } from '@app/storage/local/shared';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import {
  isMidMediaCanplayMessage,
  isMidMediaEndedMessage,
  isMidMediaErrorMessage,
} from '@content/scripts/media/midMedia/utils';
import { browser_api } from '@app/browser_api';
import { getRegionKey } from '@content/i18n/utils';
import { PremiumActions } from '@app/actions/premium';
import { isPremiumMessageOfType } from '@app/messages/premium';
import { Events } from '@app/events';
import {
  getYouTubePlayerState,
  isYTMethodResultMessage,
  pauseYouTubePlayer,
  playYouTubePlayer,
} from '../shared/utils';
import { YTPlayerState } from '../shared/types';
import { MidMediaContentMessageTypes } from './types';
import { detectBrowser } from '@app/utils/detectBrowser';
import { shouldShowMedia } from '@content/utils/shouldShowMedia';
import { logger } from '@utils/logger';

const hideMidMedia = async (overlay: HTMLElement) => {
  overlay.style.visibility = 'hidden';
  overlay.style.pointerEvents = 'none';
  playYouTubePlayer();
};

const tryToPlayMidMedia = async () => {
  const { extensionMonitoring, isPreMediaCurrentlyShown } =
    await getLocalStorageData([
      LocalStorageKey.ExtensionMonitoring,
      LocalStorageKey.IsPreMediaCurrentlyShown,
    ]);

  const adBlockerMonitoring = extensionMonitoring?.adBlocker;

  if (
    adBlockerMonitoring?.hasConflictingExtension ||
    Boolean(isPreMediaCurrentlyShown)
  ) {
    return;
  }

  const playerState = await getYouTubePlayerState();
  if (playerState !== YTPlayerState.PLAYING) {
    return;
  }

  const iframe = document.getElementById(
    MID_MEDIA_IFRAME_ID,
  ) as HTMLIFrameElement | null;

  if (!iframe) {
    return;
  }

  iframe.contentWindow?.postMessage(
    {
      type: MidMediaContentMessageTypes.MIDPOINT_MEDIA_SHOW,
    },
    '*',
  );
};

const onMessageListener = async (event: MessageEvent) => {
  const data = event.data;

  if (isYTMethodResultMessage(data)) {
    return;
  }

  const overlay = document.getElementById(MID_MEDIA_OVERLAY_ID);

  if (!overlay) {
    return;
  }

  if (isMidMediaEndedMessage(data)) {
    hideMidMedia(overlay);
    return;
  }

  if (isMidMediaErrorMessage(data)) {
    logger.error('[midpoint] No mid-Media URL found.', data.error);
    hideMidMedia(overlay);
    return;
  }

  if (isMidMediaCanplayMessage(data)) {
    pauseYouTubePlayer();
    overlay.style.visibility = 'visible';
    overlay.style.pointerEvents = 'auto';
    return;
  }
};

const addListeners = () => {
  window.addEventListener('message', onMessageListener);
};

const removeMidMedia = () => {
  window.removeEventListener('message', onMessageListener);

  const overlay = document.getElementById(MID_MEDIA_OVERLAY_ID);
  if (overlay) {
    overlay.remove();
  }
};

const injectMidMedia = async (midMediaUrl: string) => {
  const player = document.getElementById(MOVIE_PLAYER_ID);
  if (!player) return;
  if (document.getElementById(MID_MEDIA_OVERLAY_ID)) return;
  const overlay = document.createElement('div');
  overlay.id = MID_MEDIA_OVERLAY_ID;
  overlay.style.cssText = `
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: black;
    z-index: 9999;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
    visibility: hidden;
    pointer-events: none;
  `;

  const iframe = document.createElement('iframe');
  iframe.id = MID_MEDIA_IFRAME_ID;
  iframe.src = midMediaUrl;
  iframe.style.cssText = `
    width: 100%;
    height: 100%;
    object-fit: contain;
  `;

  addListeners();
  overlay.appendChild(iframe);
  player.appendChild(overlay);
};

async function checkMidMedia() {
  try {
    if (location.pathname !== '/watch') {
      removeMidMedia();
      return;
    }
    const urlParams = new URLSearchParams(location.search);
    if (!urlParams.has('v')) return;

    const { hasPremium, metaApiData, currentLocale } =
      await getLocalStorageData([
        LocalStorageKey.HasPremium,
        LocalStorageKey.MetaApiData,
        LocalStorageKey.CurrentLocale,
      ]);

    if (hasPremium || currentLocale !== 'ru') {
      return;
    }

    const { midpointMediaUrls, mediaMaxVersionChrome, mediaMaxVersionFirefox } =
      metaApiData ?? {};
    const isFirefox = detectBrowser() === 'firefox';

    const key = await getRegionKey();
    const midMediaUrl = midpointMediaUrls?.[key];

    if (!midMediaUrl) {
      logger.error('[midpoint] No URL found.');
      return;
    }

    if (isFirefox && !mediaMaxVersionFirefox) {
      logger.error('[midpoint] mediaMaxVersionFirefox are missing');
      return;
    }

    if (!isFirefox && !mediaMaxVersionChrome) {
      logger.error('[midpoint] mediaMaxVersionChrome are missing');
      return;
    }

    const currentVersion = browser_api.runtime.getManifest().version;
    const shouldShow = shouldShowMedia(
      currentVersion,
      isFirefox,
      mediaMaxVersionChrome,
      mediaMaxVersionFirefox,
    );

    if (!shouldShow) {
      logger.error(
        isFirefox
          ? '[midpoint] mediaMaxVersionFirefox is lower than current version'
          : '[midpoint] mediaMaxVersionChrome is lower than current version',
      );
      return;
    }

    void injectMidMedia(midMediaUrl);
  } catch (e) {
    logger.error('[midpoint] error:', e);
  }
}

const showMidMediaListener = (message: unknown) => {
  if (!isPremiumMessageOfType(message, PremiumActions.ShowMidpoint)) {
    return;
  }

  void tryToPlayMidMedia();
};

if (!browser_api.runtime.onMessage.hasListener(showMidMediaListener)) {
  browser_api.runtime.onMessage.addListener(showMidMediaListener);
}

void checkMidMedia();

window.addEventListener(Events.YtNavigateFinish, checkMidMedia);

window.addEventListener('popstate', checkMidMedia);
