import { PLAYER_CONTROL_KEYS, YTB_SCRIPT_SOURCE } from './constants';
import {
  YTbPlayer,
  YTMessageTypes,
  YTMethodCallMessage,
  YTMethodResultMessage,
} from './types';
import { MOVIE_PLAYER_ID } from './constants';

export const isYTMethodResultMessage = (
  data: YTMethodResultMessage,
): data is YTMethodResultMessage => {
  return (
    data &&
    data.source === YTB_SCRIPT_SOURCE &&
    data.type === YTMessageTypes.YT_METHOD_RESULT
  );
};

const callYTMethod = (method: keyof YTbPlayer) => {
  window.postMessage(
    {
      source: YTB_SCRIPT_SOURCE,
      type: YTMessageTypes.YT_METHOD_CALL,
      method,
    } satisfies YTMethodCallMessage,
    '*',
  );
};

const getMoviePlayer = (): (HTMLElement & Partial<YTbPlayer>) | null => {
  return document.getElementById(MOVIE_PLAYER_ID) as
    | (HTMLElement & Partial<YTbPlayer>)
    | null;
};

const pausePlayerFallback = () => {
  const html5Video = document.querySelector('video');
  if (html5Video && !html5Video.paused) {
    html5Video.pause();
  }

  const moviePlayer = getMoviePlayer();
  if (moviePlayer && typeof moviePlayer.pauseVideo === 'function') {
    moviePlayer.pauseVideo();
  }
};

const playPlayerFallback = () => {
  const moviePlayer = getMoviePlayer();
  if (moviePlayer && typeof moviePlayer.playVideo === 'function') {
    moviePlayer.playVideo();
  }
};

const keyboardHandler = (event: KeyboardEvent) => {
  if (PLAYER_CONTROL_KEYS.includes(event.key)) {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
  }
};

const blockPlayerKeyboardControls = () => {
  document.addEventListener('keydown', keyboardHandler, true);
  document.addEventListener('keyup', keyboardHandler, true);
};

const unBlockPlayerKeyboardControls = () => {
  document.removeEventListener('keydown', keyboardHandler, true);
  document.removeEventListener('keyup', keyboardHandler, true);
};

export const pauseYouTubePlayer = () => {
  callYTMethod('pauseVideo');
  pausePlayerFallback();
  blockPlayerKeyboardControls();
};
export const playYouTubePlayer = () => {
  callYTMethod('playVideo');
  playPlayerFallback();
  unBlockPlayerKeyboardControls();
};

export const getYouTubePlayerState = (): Promise<number | null> => {
  return new Promise((resolve) => {
    const timeout = setTimeout(() => {
      window.removeEventListener('message', handler);
      resolve(null);
    }, 1000);

    const handler = (event: MessageEvent) => {
      if (isYTMethodResultMessage(event.data)) {
        clearTimeout(timeout);
        window.removeEventListener('message', handler);
        const result = event.data.result;
        resolve(typeof result === 'number' ? result : null);
      }
    };

    window.addEventListener('message', handler);
    callYTMethod('getPlayerState');
  });
};
