import {
  MidMediaCanplayMessage,
  MidMediaEndedMessage,
  MidMediaErrorMessage,
  MidMediaMessageTypes,
} from '@content/scripts/media/midMedia/types';

export const isMidMediaEndedMessage = (
  data: MidMediaEndedMessage,
): data is MidMediaEndedMessage => {
  return data && data.type === MidMediaMessageTypes.MIDPOINT_MEDIA_ENDED;
};

export const isMidMediaErrorMessage = (
  data: MidMediaErrorMessage,
): data is MidMediaErrorMessage => {
  return data && data.type === MidMediaMessageTypes.MIDPOINT_MEDIA_ERROR;
};

export const isMidMediaCanplayMessage = (
  data: MidMediaCanplayMessage,
): data is MidMediaCanplayMessage => {
  return data && data.type === MidMediaMessageTypes.MIDPOINT_MEDIA_CANPLAY;
};
