export enum MidMediaMessageTypes {
  MIDPOINT_MEDIA_ENDED = 'MIDPOINT_MEDIA_ENDED',
  MIDPOINT_MEDIA_ERROR = 'MIDPOINT_MEDIA_ERROR',
  MIDPOINT_MEDIA_CANPLAY = 'MIDPOINT_MEDIA_CANPLAY',
}

export enum MidMediaContentMessageTypes {
  MIDPOINT_MEDIA_SHOW = 'MIDPOINT_MEDIA_SHOW',
}

export interface MidMediaEndedMessage {
  type: MidMediaMessageTypes.MIDPOINT_MEDIA_ENDED;
}

export interface MidMediaErrorMessage {
  type: MidMediaMessageTypes.MIDPOINT_MEDIA_ERROR;
  error: unknown;
}

export interface MidMediaCanplayMessage {
  type: MidMediaMessageTypes.MIDPOINT_MEDIA_CANPLAY;
}
